(** StepFieldsMorph.v: generated by scripts/generate_step_fields_morph.py.
    Field equations of [step_next] for MORPH_ID, MORPH_DELETE, MORPH_ASSERT,
    MORPH_GET and MORPH_TENSOR at their legacy and extended encodings, with symbolic
    operand, cost and ext0 bits. Each lemma is proved by reducing the actual
    decoded CPU action. *)
Require Import Kami.Kami Kami.Semantics.
From Coq Require Import String NArith Eqdep_dec Arith.PeanoNat.
From KamiHW Require Import ThieleTypes ThieleCPUCore HWBoundary RuleNext RuleStep
  BoundaryDecoded ActionObservation DispatchObservation StepEval StepFields.
Open Scope string_scope.

Definition bits32 (e0 e1 e2 e3 e4 e5 e6 e7 e8 e9 e10 e11 e12 e13 e14 e15 e16 e17 e18 e19 e20 e21 e22 e23 e24 e25 e26 e27 e28 e29 e30 e31 : bool) : word 32 :=
  WS e0 (WS e1 (WS e2 (WS e3 (WS e4 (WS e5 (WS e6 (WS e7 (WS e8 (WS e9 (WS e10 (WS e11 (WS e12 (WS e13 (WS e14 (WS e15 (WS e16 (WS e17 (WS e18 (WS e19 (WS e20 (WS e21 (WS e22 (WS e23 (WS e24 (WS e25 (WS e26 (WS e27 (WS e28 (WS e29 (WS e30 (WS e31 (WO)))))))))))))))))))))))))))))))).

Definition bits2 (x0 x1 : bool) : word 2 := WS x0 (WS x1 WO).

(** Version 2, format [fmt], flags 4 (subtype 0, descriptor kind 0, inline
    length 4), ext1 zero, extension word [e]; low lane as in [legacy_word]. *)
Definition rich_word (fmt : N) (op a b c : word 8) (e : word 32) : word InstrSz :=
  combine c (combine b (combine a (combine op (combine e
    (NToWord 64 (N.lor (N.shiftl 2 56) (N.lor (N.shiftl fmt 48) (N.shiftl 4 32)))))))).

(** Extended encodings leave comparisons between constants (the inline
    length against 8) folded, because [hw_lazy] keeps [wlt_dec] opaque for
    the symbolic guards. Decide each closed comparison, then continue as
    [hw_field]. *)
Ltac drop_closed_wlt :=
  repeat match goal with
  | |- context [wlt_dec ?x ?y] =>
      let v := eval vm_compute in (Nat.ltb (wordToNat x) (wordToNat y)) in
      lazymatch v with
      | true => let Hc := fresh "Hc" in
          destruct (wlt_dec x y) as [Hc|Hc];
          [clear Hc | exfalso; apply Hc; apply lt_wlt; apply Nat.ltb_lt; vm_compute; reflexivity]
      | false => let Hc := fresh "Hc" in
          destruct (wlt_dec x y) as [Hc|Hc];
          [exfalso; apply wlt_lt, Nat.ltb_lt in Hc; vm_compute in Hc; discriminate Hc | clear Hc]
      end
  end.

Ltac hw_field_rich :=
  intros;
  match goal with H : step_fetched _ = _ |- _ => rewrite (step_next_fetched _ _ H) end;
  cbn [hwb_after hw_pc hw_mu hw_err hw_halted hw_regs hw_mem hw_imem hw_partition_ops hw_mdl_ops hw_info_gain hw_error_code hw_logic_acc hw_cert_addr hw_active_module hw_mstatus hw_mcycle_lo hw_mcycle_hi hw_minstret_lo hw_minstret_hi hw_trap_vector hw_certified hw_lassert_phase hw_lassert_kind hw_lassert_fbase hw_lassert_cbase hw_lassert_flen hw_lassert_clen hw_lassert_nvars hw_lassert_fptr hw_lassert_cptr hw_lassert_fbuf hw_lassert_cbuf hw_lassert_clause_sat hw_lassert_counter_clause_sat hw_lassert_counter_seen_fail hw_chsh_phase hw_chsh_n00 hw_chsh_n01 hw_chsh_n10 hw_chsh_n11 hw_chsh_d00 hw_chsh_d01 hw_chsh_d10 hw_chsh_d11 hw_chsh_sign00 hw_chsh_sign01 hw_chsh_sign10 hw_chsh_sign11 hw_chsh_n00sq hw_chsh_n01sq hw_chsh_n10sq hw_chsh_n11sq hw_chsh_d00sq hw_chsh_d01sq hw_chsh_d10sq hw_chsh_d11sq hw_chsh_A_pos hw_chsh_A_neg_a hw_chsh_A_neg_b hw_chsh_B_pos hw_chsh_B_neg_a hw_chsh_B_neg_b hw_chsh_d00d01 hw_chsh_n10n11 hw_chsh_d10d11 hw_chsh_n00n01 hw_chsh_abs_C1 hw_chsh_abs_C2 hw_chsh_C_sq hw_chsh_A_times_B hw_chsh_check_result hw_bus_load_instr_addr hw_bus_load_instr_data hw_bus_load_instr_kick hw_mu_tensor hw_module_tensors hw_csr_status hw_csr_heap_base hw_ptTable hw_pt_next_id hw_morph_src_table hw_morph_dst_table hw_morph_coupling_desc_table hw_morph_valid_table hw_morph_identity_table hw_morph_next_id hw_coupling_desc_base_table hw_coupling_desc_count_table hw_coupling_desc_valid_table hw_coupling_desc_label_table hw_coupling_desc_label_len_table hw_coupling_desc_next_id hw_coupling_pair_src_table hw_coupling_pair_dst_table hw_coupling_pair_valid_table hw_coupling_pair_next_id hw_mc_phase hw_mc_op hw_mc_mem_base hw_mc_pair_count hw_mc_read_ptr hw_mc_src1_base hw_mc_src1_count hw_mc_src2_base hw_mc_src2_count hw_mc_i hw_mc_j hw_mc_is_id1 hw_mc_is_id2 hw_mc_write_base hw_mc_write_ptr hw_mc_norm_ptr hw_mc_duplicate hw_mc_dst_reg hw_mc_morph_slot hw_mc_new_src_mod hw_mc_new_dst_mod hw_mc_cost hw_formula_desc_base_table hw_formula_desc_count_table hw_formula_desc_valid_table hw_formula_desc_next_id hw_cert_desc_base_table hw_cert_desc_count_table hw_cert_desc_valid_table hw_cert_desc_next_id hw_desc_meta_subtype_table hw_desc_meta_kind_table hw_desc_meta_inline_len_table hw_desc_meta_aux_table hw_desc_meta_valid_table hw_desc_meta_next_id hw_wc_same_00 hw_wc_diff_00 hw_wc_same_01 hw_wc_diff_01 hw_wc_same_10 hw_wc_diff_10 hw_wc_same_11 hw_wc_diff_11];
  unfold hwb_decoded;
  repeat match goal with H : hwb_bianchi _ = _ |- _ => rewrite H end;
  hw_lazy; clear_concrete_word_casts; hw_lazy; drop_closed_wlt; hw_lazy; hw_split_close.

(** Morph allocation room: [morph_next_id] below 16. *)
Definition hw_morph_room (b : HWB) : bool :=
  if wlt_dec (hw_morph_next_id b) (natToWord MorphTableNextIdSz 16) then true else false.

(** Module presence: nonzero partition-table size. *)
Definition hw_module_present (b : HWB) (m : word PTableIdxSz) : bool :=
  if weq (hw_ptTable b m) (natToWord WordSz 0) then false else true.

(** A morph slot is live when it is below [morph_next_id] and marked valid. *)
Definition hw_morph_live (b : HWB) (i : word MorphTableIdxSz) : bool :=
  if wlt_dec (zext i 1) (hw_morph_next_id b) then hw_morph_valid_table b i else false.

(** A coupling descriptor reference is acceptable to MORPH_GET when it is the
    empty descriptor 0, or below the next id and marked valid. *)
Definition hw_coupling_ref_ok (b : HWB) (d : word DescIdxSz) : bool :=
  if weq d (natToWord DescIdxSz 0) then true
  else if wlt_dec (zext d 1) (hw_coupling_desc_next_id b)
       then hw_coupling_desc_valid_table b d else false.

(** Coupling-descriptor allocation room: [coupling_desc_next_id] below 16. *)
Definition hw_desc_room (b : HWB) : bool :=
  if wlt_dec (hw_coupling_desc_next_id b) (natToWord DescTableNextIdSz 16) then true else false.

(** MORPH_GET readout for a selector. *)
Definition hw_morph_get_value (b : HWB) (i : word MorphTableIdxSz) (sel : word 2) : word WordSz :=
  if weq sel (natToWord 2 0) then zext (hw_morph_src_table b i) 26
  else if weq sel (natToWord 2 1) then zext (hw_morph_dst_table b i) 26
  else if weq sel (natToWord 2 2) then
    zext (if weq (hw_morph_coupling_desc_table b i) (natToWord DescIdxSz 0)
          then natToWord CouplingPairCountSz 0
          else hw_coupling_desc_count_table b (hw_morph_coupling_desc_table b i)) 27
  else if hw_morph_identity_table b i then natToWord WordSz 1 else natToWord WordSz 0.

Definition morph_id_word (a0 a1 a2 a3 a4 a5 a6 a7 b0 b1 b2 b3 b4 b5 b6 b7 c0 c1 c2 c3 c4 c5 c6 c7 : bool) : word InstrSz :=
  legacy_word OP_MORPH_ID (bits8 a0 a1 a2 a3 a4 a5 a6 a7) (bits8 b0 b1 b2 b3 b4 b5 b6 b7) (bits8 c0 c1 c2 c3 c4 c5 c6 c7).
Lemma step_morph_id_pc : forall a0 a1 a2 a3 a4 a5 a6 a7 b0 b1 b2 b3 b4 b5 b6 b7 c0 c1 c2 c3 c4 c5 c6 c7 b,
  step_fetched b = morph_id_word a0 a1 a2 a3 a4 a5 a6 a7 b0 b1 b2 b3 b4 b5 b6 b7 c0 c1 c2 c3 c4 c5 c6 c7 -> hwb_bianchi b = false ->
  hw_pc (step_next b) = if hw_morph_room b then wplus (hw_pc b) (natToWord WordSz 1) else hw_trap_vector b.
Proof. hw_field. Qed.
Lemma step_morph_id_mu : forall a0 a1 a2 a3 a4 a5 a6 a7 b0 b1 b2 b3 b4 b5 b6 b7 c0 c1 c2 c3 c4 c5 c6 c7 b,
  step_fetched b = morph_id_word a0 a1 a2 a3 a4 a5 a6 a7 b0 b1 b2 b3 b4 b5 b6 b7 c0 c1 c2 c3 c4 c5 c6 c7 -> hwb_bianchi b = false ->
  hw_mu (step_next b) = wplus (hw_mu b) (zext (bits8 c0 c1 c2 c3 c4 c5 c6 c7) 24).
Proof. hw_field. Qed.
Lemma step_morph_id_err : forall a0 a1 a2 a3 a4 a5 a6 a7 b0 b1 b2 b3 b4 b5 b6 b7 c0 c1 c2 c3 c4 c5 c6 c7 b,
  step_fetched b = morph_id_word a0 a1 a2 a3 a4 a5 a6 a7 b0 b1 b2 b3 b4 b5 b6 b7 c0 c1 c2 c3 c4 c5 c6 c7 -> hwb_bianchi b = false ->
  hw_err (step_next b) = if hw_morph_room b then if hw_module_present b (split1 6 2 (bits8 b0 b1 b2 b3 b4 b5 b6 b7)) then false else true else true.
Proof. hw_field. Qed.
